import { useEffect, useState } from 'react';
import { api } from '../../api/api';
import PageHeader from '../../components/PageHeader';

export default function AdminTeachers() {
  const [teachers, setTeachers] = useState([]);
  useEffect(() => { api('/admin/teachers').then(setTeachers); }, []);

  return (
    <div>
      <PageHeader title="Teachers" subtitle="Academic staff members" />
      <div className="card">
        <table className="table table--striped">
          <thead><tr><th>#</th><th>Name</th><th>Staff No</th><th>Subjects</th><th>Form Class</th><th>Phone</th></tr></thead>
          <tbody>
            {teachers.map((t, i) => (
              <tr key={t.id}>
                <td>{i + 1}</td><td>{t.name}</td><td>{t.staffNo}</td>
                <td>{t.subjects.join(', ')}</td><td>{t.formClass}</td><td>{t.phone}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
